import { Amplify } from 'aws-amplify';
import awsExports from './aws-exports.js';

// amplify_outputs.json is generated by the Amplify build (Gen 2 backend) and is not
// committed. When it exists it describes both sign-in and the member-data API.
// When it doesn't (local development, or before the backend is set up), we fall
// back to the hand-written sign-in config so the site and logins keep working.
const generated = import.meta.glob('../amplify_outputs.json', { eager: true, import: 'default' });
const outputs = Object.values(generated)[0];

export const hasDataBackend = Boolean(outputs?.data?.url);

export function configureAmplify() {
  Amplify.configure(outputs ?? awsExports);
}
